def svg(name):
 return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[name][2]+'</svg>'
for name in paths:
 (ICONS / f'{name}.svg').write_text(svg(name)+'\n')
(HERE/'icon-manifest.json').write_text(json.dumps([{'id':k,'label':v[0],'meaning':v[1],'viewBox':[0,0,24,24],'strokeWidth':1.8} for k,v in paths.items()],ensure_ascii=False,indent=2)+'\n')
def tile(name):
 label, meaning, _ = paths[name]
 return f'<div class="tile"><div class="enlarged">{svg(name)}</div><b>{label}</b><small>{meaning}</small><div class="actual"><span>{svg(name)}</span><span class="active">{svg(name)}</span><span class="dark">{svg(name)}</span><em>24px</em></div></div>'
def nav(selected):
 return '<div class="nav">'+''.join(f'<div class="nav-item {"on" if k==selected else ""}">{svg(k)}<span>{paths[k][0]}</span></div>' for k in ['checkin','rewards','stats','me'])+'</div>'
stickers=[('first-step','从第一项打卡开始','记录一个想坚持的小行动。','暂无打卡','专注写字'),('waiting-message','暂时没有消息','新消息会出现在这里。','空收件箱','手机时光'),('archive','暂时没有归档打卡','归档后，历史记录会留在这里。','暂无归档','打工小鸭'),('inventory','你的物品，慢慢收集','获得的装扮与奖励会放在这里。','暂无物品','零食片刻')]
def sticker_tile(s):
 name,title,body,use,source=s
 return f'<div class="sticker-tile"><div class="sticker-stage"><img src="stickers/{name}.png" alt="{source}小鸭贴纸"></div><b>{use}</b><small>原图：{source} · 透明底</small><div class="sticker-actual"><img src="stickers/{name}.png" alt="64px实际大小"><span>实际显示 64px</span></div></div>'
